  function codes(text,course){var prefix=course==='awt'?'AWT':'WT',found=String(text||'').match(new RegExp('\\b'+prefix+'\\s+[1-9]\\.[1-9]','g'))||[];return unique(found.map(function(x){return x.replace(/\s+/g,' ');})).sort();}
