  function mapUnits(course,maps){var out=[];list(maps&&maps[course]).forEach(function(q,qi){list(q.units).forEach(function(u,ui){out.push({sourceKey:course+'-q'+(qi+1)+'-u'+(ui+1),course:course,quarterIndex:qi,unitIndex:ui,quarter:q.name,timeframe:u.timeframe,focus:u.focus,standards:u.standards,learningTargets:u.learningTargets,criteria:u.criteria,strategies:u.strategies,assessment:u.assessment,standardCodes:codes(u.standards,course)});});});return out;}
